gsl::index i = 0;
while (i < v.size()) {
    // ... do something with v[i] ...
}

for (const auto& x : v) { /* do something with the value of x */ }

for (auto& x : v) { /* modify x */ }

for_each(v, [](int x) { /* do something with the value of x */ });
