examples.code:
// Bad: Deep nesting
void foo() {
    ...
    if (x) {
        computeImportantThings(x);
    }
}

// Bad: Still a redundant else.
void foo() {
    ...
    if (!x) {
        return;
    }
    else {
        computeImportantThings(x);
    }
}

// Good: Early return, no redundant else
void foo() {
    ...
    if (!x)
        return;

    computeImportantThings(x);
}

examples.description:
Use a guard-clause to take care of exceptional cases and return early.
// Bad: Deep nesting
void foo() {
 ...
 if (x) {
 computeImportantThings(x);
 }
}

// Bad: Still a redundant else.
void foo() {
 ...
 if (!x) {
 return;
 }
 else {
 computeImportantThings(x);
 }
}

// Good: Early return, no redundant else
void foo() {
 ...
 if (!x)
 return;

 computeImportantThings(x);
}

