 // requires Regular<T> && Allocator<A>
class List {
public:
 struct Link { // does not depend on A
 T elem;
 Link* pre;
 Link* suc;
 };

 using iterator = Link*;

 iterator first() const { return head; }

 // ...
private:
 Link* head;
};

List<int> lst1;
List<int, My_allocator> lst2;

